};

function tgEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// T(lang, key, vars): the text with {name} replaced by the ESCAPED value of vars.name (raw: vars._raw.name).
function T(lang, key, vars = {}) {
  const table = TG_TEXTS[lang] || TG_TEXTS.fr;
  const s = table[key] !== undefined ? table[key] : TG_TEXTS.fr[key];
  return String(s).replace(/\{(\w+)\}/g, (_, k) => (vars._raw && vars._raw[k] !== undefined ? vars._raw[k] : tgEsc(vars[k] ?? '')));
}

const TG_EXP = { TND: 3, EUR: 2, GBP: 2, USD: 2 };
function tgMoney(minor, cur, exp) {
  if (minor === null || minor === undefined || !cur) return null;
  const e = exp !== undefined && exp !== null ? Number(exp) : (TG_EXP[cur] ?? 2);
  const v = Number(minor) / Math.pow(10, e);
  const shown = String(Number(v.toFixed(Math.min(e, 2))));
  return cur === 'GBP' ? `£${shown}` : cur === 'EUR' ? `${shown} €` : `${shown} ${cur === 'TND' ? 'DT' : cur}`;
}

function tgLang(code) {
  const c = String(code || '').slice(0, 2).toLowerCase();
  return c === 'ar' ? 'ar' : c === 'en' ? 'en' : 'fr';
}

// A failed API call in plain words, or null when it succeeded.
function tgApiError(lang, r) {
  if (r && r.status >= 200 && r.status < 300) return null;
  const code = (r && r.error_code) || 'NO_ANSWER';
  if (r && r.status === 429) return T(lang, 'rate');
  if (!r || !r.status || r.status === 503) return T(lang, 'down');
  if (code === 'CONSENT_REQUIRED') return T(lang, 'consent_needed');
  return T(lang, 'failed', { code });
}

if (typeof module !== 'undefined') module.exports = { T, tgEsc, tgMoney, tgLang, tgApiError, TG_TEXTS, TG_ISSUES, TG_RULES };

const P = $('Plan').first().json;
const r = $input.first().json;
const err = tgApiError(P.lang, r);
let text;
if ('Done: consent' === 'No account') text = P.text;
else if (err) text = err;
else if (P.route === 2) text = `${T(P.lang, 'welcome')}\n\n${T(P.lang, 'help', { country: P.country })}${P.role === 'admin' ? T(P.lang, 'help_admin') : ''}`;
else if (P.route === 3) text = P.text;
else text = T(P.lang, 'country_set', { country: P.new_country });
return [{ json: { chat_id: P.chat_id, text } }];

// wf.channel.telegram > "Call: record consent": the input of wf.channel.telegram.api for one API call.
// The Telegram channel uses the public API like any client (D-079): signature, consent and rate limits apply.
const CALL = 'record consent';
const P = $('Plan').first().json;
const idem = (suffix) => `tg-${P.update_id}-${suffix}`;
const listingId = () => $('API: create listing').first().json.body.data.listing_id;
let call;
switch (CALL) {
  case 'sync user':
    call = { method: 'POST', path: '/v1/users/sync', idem: idem('sync'),
      body: { external_auth_id: P.ext_id, locale: P.lang, jurisdiction_code: P.new_country || P.country } };
    break;
  case 'record consent': {
    const yes = P.route === 2;
    const user = yes ? $('API: sync user').first().json.body.data.user_id : P.user_id;
    call = { method: 'POST', path: '/v1/me/consents', user_id: user, idem: idem('consent'),
      body: { consents: ['terms', 'privacy', 'media_processing'].map((purpose) => ({ purpose, granted: yes })),
        policy_version: P.policy_version, source: 'telegram' } };
    break;
  }
  case 'ask assistant':
    call = { method: 'POST', path: '/v1/assistant/message', user_id: P.user_id, idem: idem('ask'),
      body: { text: P.text.slice(0, 2000), jurisdiction: P.country } };
    break;
  case 'trace':
    call = { method: 'GET', path: `/v1/admin/traces/${encodeURIComponent(P.last_request_id)}`, user_id: P.user_id };
    break;
  case 'create listing':
    call = { method: 'POST', path: '/v1/listings', user_id: P.user_id, idem: idem('listing'),
      body: { text: P.listing_text.slice(0, 5000), jurisdiction_code: P.country } };
    break;
  case 'presign': {
    const d = $('Download photo').first();
    const mime = (d.binary && d.binary.data && d.binary.data.mimeType) || 'image/jpeg';
    call = { method: 'POST', path: `/v1/listings/${listingId()}/media/presign`, user_id: P.user_id, idem: idem('presign'),
      body: { files: [{ kind: 'photo', content_type: ['image/png', 'image/webp'].includes(mime) ? mime : 'image/jpeg',
        bytes: Number((d.json.result || {}).file_size) || 1 }] } };
    break;
  }
  case 'analyze':
    call = { method: 'POST', path: `/v1/listings/${listingId()}/analyze`, user_id: P.user_id, idem: idem('analyze'), body: {} };
    break;
  case 'job':
    call = { method: 'GET', path: `/v1/jobs/${$('API: analyze').first().json.body.data.job_id}`, user_id: P.user_id };
    break;
  case 'get listing':
    call = { method: 'GET', path: `/v1/listings/${listingId()}`, user_id: P.user_id };
    break;
  default:
    throw new Error(`unknown call ${CALL}`);
}
return [{ json: call }];

