else if (P.route === 2) text = `${T(P.lang, 'welcome')}\n\n${T(P.lang, 'help', { country: P.country })}${P.role === 'admin' ? T(P.lang, 'help_admin') : ''}`;
else if (P.route === 3) text = P.text;
else text = T(P.lang, 'country_set', { country: P.new_country });
